def maxSpacing(points, k):
    n = len(points)
    INF = float('inf')
    dist = [INF] * n
    used = [False] * n
    dist[0] = 0
    weights = []
    for step in range(n):
        u = -1
        best = INF
        for i in range(n):
            if not used[i] and dist[i] < best:
                best = dist[i]
                u = i
        used[u] = True
        if step > 0:
            weights.append(best)
        ux, uy = points[u]
        for i in range(n):
            if not used[i]:
                d = abs(points[i][0] - ux) + abs(points[i][1] - uy)
                if d < dist[i]:
                    dist[i] = d
    weights.sort(reverse=True)
    return weights[k - 2]
